CREATE TABLE IF NOT EXISTS studio_tasks(id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, completed BIGINT NOT NULL DEFAULT 0, created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX studio_tasks_owner ON studio_tasks(user_id,id);
CREATE TABLE IF NOT EXISTS studio_reports(id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, job_id BIGINT NOT NULL UNIQUE, total BIGINT NOT NULL, completed BIGINT NOT NULL, created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
